package sdk

// GetServerURL returns the configured base server URL.
// Used by custom resources/data sources that make raw HTTP calls
// to endpoints not generated by Speakeasy.
func (s *TerraformProviderNs) GetServerURL() string {
	url, _ := s.sdkConfiguration.GetServerDetails()
	return url
}

// GetHTTPClient returns the underlying HTTP client used by the SDK.
// Used by custom resources/data sources to reuse the same transport
// (including any hooks applied via SDKInit).
func (s *TerraformProviderNs) GetHTTPClient() HTTPClient {
	return s.sdkConfiguration.Client
}
